use super::*;
use semio_framework_value::{DslValue,NativeDecodeControl,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,ValueError,retained_clone::{RetainedCloneSource,retained_clone_grant_admits},retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_native_owned::native_decoding::{NativeReceiver,NativeDecodeConstructionRecipient};
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
struct Turn(RetainedCloneGrant);
impl NativeDecodeConstructionRecipient for Turn{fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(retained_clone_grant_admits(self.0,d));Ok(self.0)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));Ok(())}}
fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native identity retirement"));for _ in 0..10000{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();let g=grant(d);assert!(owner.step(g).unwrap().progress().fits(g));}panic!("native identity retirement stalled")}
fn receive<T:NativeReceive<dyn NativeValueSource>>(row:&serde_json::Value,observe:impl Fn(&T)->serde_json::Value){
 let source={let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<16,maximum_capacity_bytes:1<<16,maximum_release_bytes:1<<20,maximum_depth:4096};let mut admission=RetainedCloneSource::admission_owned(DslValue::from(&row["input"]),());let mut output=None;for _ in 0..64{if admission.terminal_is_empty(){break}if admission.phase()=="ready"{admission.take_output(&mut output,g).result.unwrap();}else{admission.advance(g).result.unwrap();}}output.expect("original identity source")};
 let mut receiver=T::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;
 for _ in 0..4096{if receiver.output_ready(){break}let original=source.borrow().project(0,|value|value.as_source());let d=match receiver.demands(original,4096){Ok(d)=>d,Err(_)=>{refused=true;break}};let g=grant(d);for denied in [(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,grant)|active.then_some(grant)){let mut turn=Turn(denied);let step=control.with_construction_recipient(&mut turn,|control|receiver.advance(original,control,4096,denied).result).unwrap();assert_eq!(step.progress(),Default::default());assert_eq!(receiver.demands(original,4096).unwrap(),d);}let mut turn=Turn(g);match control.with_construction_recipient(&mut turn,|control|receiver.advance(original,control,4096,g).result){Ok(step)=>assert!(step.progress().fits(g)),Err(_)=>{refused=true;break}}}
 let accepted=row["accepted"].as_bool().unwrap();assert_eq!(receiver.output_ready()&&!refused,accepted);let output=if accepted{let g=grant(receiver.take_demand().unwrap());let(value,p)=receiver.take(g).result.unwrap().unwrap();assert!(p.fits(g));assert_eq!(observe(&value),row["expected"]);Some(value)}else{None};
 receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let g=grant(receiver.close_demands(4096).unwrap());assert!(receiver.close_step(g).result.unwrap().progress().fits(g));}assert!(receiver.terminal_is_empty());assert_eq!(serde_json::Value::from(source.borrow().get()),row["input"]);drop(receiver);if let Some(output)=output{drain(output)}drain(source);
}
#[test]fn schema_and_payload_hash_receive_actual_erased_original_sources(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){if row["kind"]=="schema"{receive::<SchemaId>(row,|value|serde_json::json!(value.0))}else{receive::<PayloadHash>(row,|value|serde_json::json!(value.0))}}}
#[test]fn schema_identity_adopts_the_completed_native_text_owner(){let text=String::from("schema:original");let pointer=text.as_ptr();let owner=<SchemaId as NativeReceiveMap<String>>::from_native(text);assert_eq!(owner.0.as_ptr(),pointer);drain(owner);}
